import{_ as l,a0 as p,w as o,s as r,I as t,x as e,a1 as i,A as n,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"使用 Ledger 記錄（財務）情況 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Ledger 記錄（財務）情況 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Ledger 記錄（財務）情況 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Ledger 記錄（財務）情況 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20141127 Keeping (financial) score with Ledger ","title":"使用 Ledger 記錄（財務）情況","tag":"201807","desc":""},"relativePath":"201807/20141127 Keeping (financial) score with Ledger .md","filePath":"[post].md"}'),g={name:"201807/20141127 Keeping (financial) score with Ledger .md"};function h(u,s,k,f,b,m){const a=p("Link");return o(),r("div",null,[s[18]||(s[18]=t("h1",{id:"使用-ledger-記錄-財務-情況",tabindex:"-1"},[e("使用 Ledger 記錄（財務）情況 "),t("a",{class:"header-anchor",href:"#使用-ledger-記錄-財務-情況","aria-label":"Permalink to “使用 Ledger 記錄（財務）情況”"},"​")],-1)),t("p",null,[s[1]||(s[1]=e("自 2005 年搬到加拿大以來，我使用 ",-1)),i(a,{href:"http://www.ledger-cli.org/"},{default:n(()=>[...s[0]||(s[0]=[e("Ledger CLI",-1)])]),_:1}),s[2]||(s[2]=e(" 來跟蹤我的財務狀況。我喜歡純文本的方式，它支持虛擬信封意味着我可以同時將我的銀行帳户餘額和我的虛擬分配到不同的目錄下。以下是我們如何使用這些虛擬信封分別管理我們的財務狀況。",-1))]),s[19]||(s[19]=d(`<p>每個月，我都有一個條目將我生活開支分配到不同的目錄中，包括家庭開支的分配。W- 不要求太多， 所以我要謹慎地處理這兩者之間的差別和我自己的生活費用。我們處理它的方式是我支付固定金額，這是貸記我支付的雜貨。由於我們的雜貨總額通常低於我預算的家庭開支，因此任何差異都會留在標籤上。我過去常常給他寫支票，但最近我只是支付偶爾額外的大筆費用。</p><p>這是個示例信封分配：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2014.10.01 * Budget</span></span>
<span class="line"><span> [Envelopes:Living]</span></span>
<span class="line"><span> [Envelopes:Household] $500</span></span>
<span class="line"><span> ;; More lines go here</span></span></code></pre></div><p>這是設置的信封規則之一。它鼓勵我正確地分類支出。所有支出都從我的 “Play” 信封中取出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>= /^Expenses/</span></span>
<span class="line"><span> (Envelopes:Play) -1.0</span></span></code></pre></div><p>這個為家庭支出報銷 “Play” 信封，將金額從 “Household” 信封轉移到 “Play” 信封。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>= /^Expenses:House$/</span></span>
<span class="line"><span> (Envelopes:Play) 1.0</span></span>
<span class="line"><span> (Envelopes:Household) -1.0</span></span></code></pre></div><p>我有一套定期的支出來模擬我的預算中的家庭開支。例如，這是 10 月份的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2014.10.1 * House</span></span>
<span class="line"><span> Expenses:House</span></span>
<span class="line"><span> Assets:Household $-500</span></span></code></pre></div><p>這是雜貨交易的形式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2014.09.28 * No Frills</span></span>
<span class="line"><span> Assets:Household:Groceries $70.45</span></span>
<span class="line"><span> Liabilities:MBNA:September $-70.45</span></span></code></pre></div><p>接着 <code>ledger bal Assets:Household</code> 就會告訴我是否欠他錢（負餘額）。如果我支付大筆費用（例如：機票、通管道），那麼正常家庭開支預算會逐漸減少餘額。</p><p>我從 W- 那找到了一個為我的信用卡交易添加一個月標籤的技巧，他還使用 Ledger 跟蹤他的交易。它允許我再次檢查條目的餘額，看看前一個條目是否已被正確清除。</p><p>這個資產分類使用有點奇怪，但它在精神上對我有用。</p><p>使用 Ledger 以這種方式跟蹤它可以讓我跟蹤我們的雜貨費用以及我實際支付費用和我預算費用之間的差額。如果我最終支出超出預期，我可以從更多可自由支配的信封中移動虛擬貨幣，因此我的預算始終保持平衡。</p><p>Ledger 是一個強大的工具。相當極客，但也許更多的工作流描述可能會幫助那些正在搞清楚它的人！</p><hr>`,17)),t("p",null,[s[4]||(s[4]=e("via: ",-1)),i(a,{href:"http://sachachua.com/blog/2014/11/keeping-financial-score-ledger/"},{default:n(()=>[...s[3]||(s[3]=[e("http://sachachua.com/blog/2014/11/keeping-financial-score-ledger/",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=e("作者：",-1)),i(a,{href:"http://sachachua.com"},{default:n(()=>[...s[5]||(s[5]=[e("Sacha Chua",-1)])]),_:1}),s[10]||(s[10]=e(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 譯者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:n(()=>[...s[7]||(s[7]=[e("geekpi",-1)])]),_:1}),s[12]||(s[12]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...s[14]||(s[14]=[e("Linux中國",-1)])]),_:1}),s[17]||(s[17]=e(" 榮譽推出",-1))])])}const T=l(g,[["render",h]]);export{L as __pageData,T as default};
